From e82048465c5ba34eafb4ed7414b8f01b68368385 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:47:46 +0100
Subject: [PATCH] FrameSvgItem: follow the Kirigami color set with themes that
 have colors

With a Plasma style that ships its own colors file, frame SVGs always
used the Window colors, so headers were darker than with the same scheme
and a style without colors. Use the item's Kirigami color set there too.

BUG: 525075
---
 autotests/svgtest.cpp                   | 1 +
 src/declarativeimports/framesvgitem.cpp | 2 ++
 src/ksvg/private/imageset_p.cpp         | 2 +-
 3 files changed, 4 insertions(+), 1 deletion(-)

diff --git a/autotests/svgtest.cpp b/autotests/svgtest.cpp
index 5526db5d..722ca430 100644
--- a/autotests/svgtest.cpp
+++ b/autotests/svgtest.cpp
@@ -199,6 +199,7 @@ void SvgTest::testStylesheetOverrideColorChange()
     KColorScheme windowColors(QPalette::Normal, KColorScheme::Window, config);
     auto set = new KSvg::ImageSet("testthemesystemcolors", "plasma/desktoptheme");
     m_svg->setImageSet(set);
+    m_svg->setColorSet(KSvg::Svg::Window);
     // Set a color override in the svg
     m_svg->setColor(KSvg::Svg::Text, Qt::blue);
     // set->setImageSetName(QStringLiteral("testthemesystemcolors"));
diff --git a/src/declarativeimports/framesvgitem.cpp b/src/declarativeimports/framesvgitem.cpp
index e12957c1..193f3fe1 100644
--- a/src/declarativeimports/framesvgitem.cpp
+++ b/src/declarativeimports/framesvgitem.cpp
@@ -695,6 +695,7 @@ void FrameSvgItem::componentComplete()
         }
     };
     auto applyTheme = [this]() {
+        setColorSet(KSvg::Svg::ColorSet(m_kirigamiTheme->colorSet()));
         if (m_frameSvg->imageSet()->hasColors()) {
             m_frameSvg->clearCache();
             m_frameSvg->clearColorOverrides();
@@ -715,6 +716,7 @@ void FrameSvgItem::componentComplete()
     applyTheme();
     connect(m_kirigamiTheme, &Kirigami::Platform::PlatformTheme::frameContrastChanged, this, applyTheme);
     connect(m_kirigamiTheme, &Kirigami::Platform::PlatformTheme::colorsChanged, this, applyTheme);
+    connect(m_kirigamiTheme, &Kirigami::Platform::PlatformTheme::colorSetChanged, this, applyTheme);
     connect(m_frameSvg->imageSet(), &ImageSet::imageSetChanged, this, checkApplyTheme);
     connect(m_frameSvg, &Svg::imageSetChanged, this, checkApplyTheme);

diff --git a/src/ksvg/private/imageset_p.cpp b/src/ksvg/private/imageset_p.cpp
index 1934fdd2..789ca82a 100644
--- a/src/ksvg/private/imageset_p.cpp
+++ b/src/ksvg/private/imageset_p.cpp
@@ -376,7 +376,7 @@ QColor ImageSetPrivate::namedColor(Svg::StyleSheetColor colorName, const KSvg::S
         if (status == Svg::Status::Selected) {
             return selectionColorScheme.background(KColorScheme::NormalBackground).color();
         } else {
-            return colorScheme.background(KColorScheme::NormalBackground).color();
+            return currentScheme->background(KColorScheme::NormalBackground).color();
         }
     case Svg::Highlight:
         return selectionColorScheme.background(KColorScheme::NormalBackground).color();
-- 
